mapper.select:
${limitBefore} select distinct RES.ID id, RES.TASK_ID_ "taskId", RES.SYS_ID_ "sysId", RES.IS_ALLOT_ "isAllot", RES.CREATE_DATE_ "createTime", RES.TENANT_ID_ "tenantId", RES.USER_ID_ "userId", RT.EXECUTION_ID_ "executionId", RT.PROC_INST_ID_ "processInstanceId", RT.PROC_DEF_ID_ "processDefinitionId", RT.NAME_ "activityName", RT.DESCRIPTION_ "description", RT.TASK_DEF_KEY_ "activityId"
,
${field}
${limitBetween}
, row_number() over (ORDER BY RES.ID ) rnk FROM ( select distinct RES.*
${limitAfter}

mapper.sql:
from ${prefix}WF_HI_TASK_POOL_EXECUTE_DATA RES
INNER JOIN ACT_RU_TASK RT ON RES.TASK_ID_ = RT.ID_
LEFT JOIN WF_TASK_EXPAND_DATA W on RES.TASK_ID_ = W.TASK_ID


  	AND RES.TASK_ID_ = #{taskId}


  	AND RES.SYS_ID_ = #{sysId}


  	AND RES.USER_ID_ = #{userId}


  	AND RES.IS_ALLOT_ = #{isAllot}


  	AND RES.TENANT_ID_ = #{tenantId}



          AND ${condition}



ORDER BY RES.CREATE_DATE_ DESC
